# List messages

List messages matching the given parameters, paginated.

# OpenAPI definition

```json
{
  "security": [
    {
      "basicAuth": []
    }
  ],
  "info": {
    "description": "The Gorgias REST API. Please go to https://developers.gorgias.com for more details.",
    "title": "Gorgias REST API",
    "version": "1.0.0"
  },
  "servers": [
    {
      "url": "https://{domain}.gorgias.com",
      "variables": {
        "domain": {
          "default": "your-domain"
        }
      }
    }
  ],
  "x-readme": {
    "proxy-enabled": false
  },
  "paths": {
    "/api/messages": {
      "get": {
        "summary": "List messages",
        "operationId": "list-messages",
        "description": "List messages matching the given parameters, paginated.",
        "parameters": [
          {
            "in": "query",
            "name": "cursor",
            "description": "Value indicating your position in the list of all messages. If omitted, the first messages of the list will be returned.",
            "schema": {
              "type": [
                "string",
                "null"
              ],
              "example": "cHJldl9fNl9fMjAyMS0wMy0wMyAwNjowMDowMA=="
            },
            "required": false
          },
          {
            "in": "query",
            "name": "limit",
            "description": "Maximum number of messages to return.",
            "schema": {
              "type": "integer",
              "default": 30,
              "minimum": 1,
              "maximum": 100
            },
            "required": false
          },
          {
            "in": "query",
            "name": "order_by",
            "description": "Attribute used to order messages.",
            "schema": {
              "type": "string",
              "default": "created_datetime:desc",
              "enum": [
                "created_datetime:asc",
                "created_datetime:desc"
              ]
            },
            "required": false
          },
          {
            "in": "query",
            "name": "ticket_id",
            "description": "The ID of the ticket the messages are associated with.",
            "schema": {
              "type": [
                "integer",
                "null"
              ],
              "default": null,
              "example": 1
            },
            "required": false
          }
        ],
        "responses": {
          "200": {
            "description": "A list of messages.",
            "content": {
              "application/json": {
                "schema": {
                  "additionalProperties": false,
                  "properties": {
                    "object": {
                      "title": "object",
                      "type": "string"
                    },
                    "uri": {
                      "title": "uri",
                      "type": "string"
                    },
                    "data": {
                      "items": {
                        "$ref": "#/components/schemas/TicketMessage"
                      },
                      "title": "data",
                      "type": "array"
                    },
                    "meta": {
                      "$ref": "#/components/schemas/CursorPaginationMeta"
                    }
                  },
                  "required": [
                    "object",
                    "uri",
                    "data",
                    "meta"
                  ],
                  "title": "paginated data",
                  "type": "object"
                }
              }
            }
          }
        },
        "tags": [
          "Ticket Messages"
        ]
      }
    }
  },
