      "TicketMessage": {
        "additionalProperties": false,
        "description": "A ticket-message represents a message (an email, an SMS, a Facebook comment, chat message, etc..) under a normalized format.\nThere are 3 types of messages:\n  - Outgoing messages: messages sent by your company (by rules or support agents) to your customers.\n  - Incoming messages: messages sent by your [customers](#the-customer-object) to your company.\n  - Internal notes: internal messages sent between support agents ([users](#the-user-object)). Internal notes are not sent/shared with your customers.\n\nA ticket-message is associated with only one ticket.",
        "properties": {
          "id": {
            "description": "ID of the message.",
            "examples": [
              924712
            ],
            "title": "id",
            "type": "integer"
          },
          "uri": {
            "description": "URI of the message.",
            "title": "uri",
            "type": "string"
          },
          "message_id": {
            "description": "ID of the message on the service that sent the message.It can be the ID of an email, a Messenger message, a Facebook comment, etc...",
            "examples": [
              "<123345676453.2445.234@web>"
            ],
            "title": "message  id",
            "type": "string"
          },
          "ticket_id": {
            "description": "The ID of the ticket the message is associated with.",
            "examples": [
              12
            ],
            "title": "ticket  id",
            "type": "integer"
          },
          "external_id": {
            "description": "ID of the message in a foreign system (Aircall, Zendesk, etc...). This field is not used by Gorgias, feel free to set it as you wish.",
            "examples": [
              "MSG-78545"
            ],
            "title": "external  id",
            "type": "string"
          },
          "public": {
            "default": true,
            "description": "Whether the message was sent/receive by a customer. Internal notes are not public.",
            "examples": [
              true
            ],
            "title": "public",
            "type": "boolean"
          },
          "channel": {
            "anyOf": [
              {
                "$ref": "#/components/schemas/LegacyChannelSlug"
              },
              {
                "type": "string"
              }
            ],
            "description": "The channel used to send the message.",
            "examples": [
              "email"
            ],
            "title": "channel"
          },
          "via": {
            "$ref": "#/components/schemas/TicketVia",
            "description": "How the message has been received, or sent from Gorgias.",
            "examples": [
              "api"
            ]
          },
          "source": {
            "description": "Information used to route the message. It contains the names and the addresses of the sender and receivers.",
            "examples": [
              {
                "from": {
                  "address": "sender@gorgias.io",
                  "id": 7,
                  "name": "Sender Doe"
                },
                "to": [
                  {
                    "address": "receiver@gorgias.io",
                    "id": 8,
                    "name": "Receiver Doe"
                  }
                ],
                "type": "email"
              }
            ],
            "$ref": "#/components/schemas/TicketMessageSource"
          },
          "sender": {
            "$ref": "#/components/schemas/TicketMessageUserOrCustomer",
            "description": "The person who sent the message. It can be a user or a customer.",
            "examples": [
              {
                "id": 93
              }
            ]
          },
          "auth_customer_identity": {
            "description": "Identity of the authenticated customer, if any, in the context of a message sent on a channel that does not require authentication such as email, SMS or Gorgias chat.This attribute is used to differentiate messages sent by unauthenticated and authenticated customers.",
            "$ref": "#/components/schemas/TicketMessageAuthCustomerIdentity"
          },
          "integration_id": {
            "description": "ID of the integration that either received or sent the message.",
            "examples": [
              28643
            ],
            "title": "integration  id",
            "type": "integer"
          },
          "intents": {
            "items": {
              "$ref": "#/components/schemas/TicketMessageIntent"
            },
            "title": "intents",
            "type": "array"
          },
          "rule_id": {
            "description": "ID of the rule which sent the message, if any.",
            "examples": [
              89465
            ],
            "title": "rule  id",
            "type": "integer"
          },
          "from_agent": {
            "description": "Whether the message was sent by your company to a customer, or the opposite.",
            "examples": [
              true
            ],
            "title": "from  agent",
            "type": "boolean"
          },
          "receiver": {
            "description": "The primary receiver of the message. It can be a user or a customer. Optional when the source type is \"internal-note\".",
            "examples": [
              {
                "id": 8
              }
            ],
            "$ref": "#/components/schemas/TicketMessageUserOrCustomer"
          },
          "subject": {
            "description": "The subject of the message.",
            "examples": [
              "Re:Refund request"
            ],
            "title": "subject",
            "type": "string"
          },
          "body_text": {
            "description": "The full text version of the body of the message, if any.",
            "examples": [
              "Hello,\n\n        I can't place an order on your site, it says: I don't have enough credit.\n        How can I add some credits?\n\n        Cheers,\n        John Doe\n        "
            ],
            "title": "body  text",
            "type": "string"
          },
          "body_html": {
            "description": "The full HTML version of the body of the message, if any.",
            "examples": [
              "Hello,<br><br>\n\n            I can't place an order on your site, it says: I don't have enough credit.<br>\n            How can I add some credits?<br><br>\n\n            Cheers,<br>\n            John Doe\n            "
            ],
            "title": "body  html",
            "type": "string"
          },
          "body_url": {
            "description": "The URL to download the archived body of the email message. Empty until the body is archived, 30 days after it was sent or received. Only applies to email messages that have stripped bodies.",
            "title": "body  url",
            "type": "string"
          },
          "stripped_text": {
            "description": "The text version of the body of the message without email signatures and previous replies.",
            "examples": [
              null
            ],
            "title": "stripped  text",
            "type": "string"
          },
          "stripped_html": {
            "description": "The HTML version of the body of the message without email signatures and previous replies.",
            "examples": [
              null
            ],
            "title": "stripped  html",
            "type": "string"
          },
          "stripped_signature": {
            "title": "stripped  signature",
            "type": "string"
          },
          "attachments": {
            "description": "A list of files attached to the message.",
            "examples": [
              []
            ],
            "title": "attachments",
            "items": {
              "$ref": "#/components/schemas/TicketMessageAttachment"
            },
            "type": "array"
          },
          "macros": {
            "description": "A list of macros.",
            "examples": [
              []
            ],
            "title": "macros",
            "items": {
              "$ref": "#/components/schemas/TicketMessageMacro"
            },
            "type": "array"
          },
          "actions": {
            "description": "A list of actions executed before the message was sent. These actions are set by macros.",
            "examples": [
              []
            ],
            "title": "actions",
            "items": {
              "type": "object"
            },
            "type": "array"
          },
          "headers": {
            "description": "Message headers. Used for email messages.",
            "examples": [
              {
                "My-Header": "foo"
              }
            ],
            "title": "headers",
            "type": "object"
          },
          "imported": {
            "description": "Whether the message was created by a historical import.",
            "examples": [
              false
            ],
            "title": "imported",
            "type": "boolean"
          },
          "meta": {
            "description": "Metadata associated with the message.\n\nYou can use this field to store structured information (key-value data) about the message.\n\nReserved keys:\n\n- `current_page`: The page from where the user is currently chatting.\n- `relevant_content_indexes`: Indexes containing relevant text of the message.\n- `is_quick_reply`: Whether the message is a \"quick reply\".\n- `campaigns`: ID of the chat campaign the message is replying to.\n- `campaigns_id`: ID of the chat campaign that sent this message.\n- `self_service_flow`: An object containing metadata of the self-service flow associated to the message.\n",
            "examples": [
              {}
            ],
            "title": "meta"
          },
          "created_datetime": {
            "description": "When the message was created.",
            "examples": [
              "2020-01-27T10:42:21.468912"
            ],
            "format": "date-time",
            "title": "created  datetime",
            "type": "string"
          },
          "processed_datetime": {
            "description": "When the message was processed by Gorgias. Differs from `created_datetime` which refers to the external service.",
            "examples": [
              "2020-01-27T10:42:21.468912"
            ],
            "title": "processed  datetime",
            "format": "date-time",
            "type": "string"
          },
          "deleted_datetime": {
            "description": "When the message was deleted.",
            "examples": [
              "2020-01-27T10:42:21.468912"
            ],
            "title": "deleted  datetime",
            "format": "date-time",
            "type": "string"
          },
          "sent_datetime": {
            "description": "When the message was sent. If omitted, the message will be sent by Gorgias.",
            "title": "sent  datetime",
            "format": "date-time",
            "type": "string"
          },
          "failed_datetime": {
            "description": "When the message failed to be sent. Messages that couldn't be sent can be resend.",
            "examples": [
              null
            ],
            "title": "failed  datetime",
            "format": "date-time",
            "type": "string"
          },
          "opened_datetime": {
            "description": "When the message was opened by the primary receiver.",
            "examples": [
              "2019-07-05T15:22:46.472436"
            ],
            "title": "opened  datetime",
            "format": "date-time",
            "type": "string"
          },
          "last_sending_error": {
            "description": "Details of the last error encountered when Gorgias attempted to send the message.",
            "examples": [
              null
            ],
            "$ref": "#/components/schemas/TicketMessageSendingError"
          },
          "is_retriable": {
            "description": "It determines if the message can be retried or not.",
            "title": "is  retriable",
            "type": "boolean"
          },
          "replied_by": {
            "description": "The message designated as a response to the current message. This field is temporary and only provided to the web app.",
            "title": "replied  by",
            "$ref": "#/components/schemas/TicketMessageRepliedByOrTo"
          },
          "replied_to": {
            "description": "The message designated as replied by the current message. This field is temporary and only provided to the web app.",
            "title": "replied  to",
            "$ref": "#/components/schemas/TicketMessageRepliedByOrTo"
          }
        },
        "required": [
          "id",
          "uri",
          "message_id",
          "ticket_id",
          "external_id",
          "channel",
